.topline{height:5px;background:linear-gradient(90deg,var(--red) 0 18%,var(--navy) 18% 100%)}.header{background:linear-gradient(115deg,#0b2a4d,var(--navy2));color:#fff}.header-inner{max-width:1260px;margin:auto;padding:27px 24px 29px;display:flex;justify-content:space-between;align-items:center;gap:20px}.eyebrow{font-weight:750;text-transform:uppercase;letter-spacing:.12em;font-size:11px;color:#9dc4e7}.header h1{font-size:clamp(22px,2.7vw,30px);letter-spacing:-.6px;margin:5px 0 5px}.header p{margin:0;color:#c4d7e8}.head-side{text-align:right}.user-tag{display:inline-flex;gap:8px;align-items:center;border:1px solid #ffffff45;background:#ffffff13;padding:7px 12px;border-radius:99px;font-weight:650}.nav-back{display:block;margin-top:11px;color:#fff;font-weight:600}.nav-back:hover{color:white}
