.orders{display:grid;grid-template-columns:repeat(auto-fill,minmax(305px,1fr));gap:15px}.order{border:1px solid #dfe8f0;border-radius:13px;overflow:hidden;background:#fff}.order.active{border-color:#7ab3e1;box-shadow:0 0 0 2px #dcebfa}.order-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:17px 18px 11px}.order-top h3{font-size:18px;margin:3px 0 0}.order-body{padding:0 18px 15px}.order-detail{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:13px 0}.order-detail span{display:block;color:var(--muted);font-size:11px}.order-detail strong{display:block;color:var(--ink);font-size:13px;overflow-wrap:anywhere}.order-actions{border-top:1px solid var(--border);padding:13px 18px;display:flex;gap:9px;flex-wrap:wrap}.btn{font:650 12.5px/1.35 "Segoe UI",system-ui,sans-serif;border:1px solid #c8d9e9;border-radius:9px;background:#fff;color:#155989;padding:10px 12px;display:inline-flex;align-items:center;justify-content:center;gap:5px;cursor:pointer;text-align:center}.btn:hover{text-decoration:none;background:#eff6fc}.btn.primary{background:#11558c;color:white;border-color:#11558c}.btn.primary:hover{background:#0c416d}.btn:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #9cc8ef;outline-offset:2px}.delivery{border-top:1px solid var(--border);background:#f8fbfe;padding:15px 18px}.delivery label{display:block;font-weight:700;font-size:12px;margin-bottom:7px}.delivery textarea{display:block;width:100%;resize:vertical;min-height:62px;font:inherit;padding:10px;border:1px solid #cddbe8;border-radius:8px;margin-bottom:10px;background:white}.delivery .btn{width:100%}.help{font-size:11px;color:var(--muted);margin:7px 0 0}.empty{padding:35px 20px;text-align:center;border:1px dashed #cddbe8;background:#fafcff;border-radius:12px;color:var(--muted)}.empty b{display:block;color:var(--ink);margin-bottom:4px}
.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:12px 13px;border-bottom:1px solid #e8edf3;vertical-align:middle}th{color:#526a82;background:#f4f8fc;font-size:11px;letter-spacing:.025em;text-transform:uppercase}td{font-size:13px}tbody tr:hover{background:#fbfdff}.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.pending{font-weight:800;color:#a74a1b}.complete{font-weight:800;color:var(--green)}.progress{width:110px;height:7px;background:#e8edf3;border-radius:20px;overflow:hidden}.progress div{height:100%;background:#21926f;border-radius:20px}.muted{color:var(--muted)}.note{margin:15px 0 0;color:var(--muted);font-size:12px}.buy-filter{display:inline-flex;gap:7px;flex-wrap:wrap;align-items:center}.buy-filter select{padding:8px 10px;border:1px solid #cbd9e7;background:white;border-radius:8px;font:inherit;min-width:155px}.history td{font-size:12px}
