<body><div class="topline"></div><header class="header"><div class="header-inner"><div><div class="eyebrow">Distribución G&amp;D · ERP de compras</div><h1><?=gyf_is_manager($u)?'Portal del gerente':'Órdenes de compra y avisos'?></h1><p><?=gyf_is_manager($u)?'Consulta tus órdenes, revisa sus pendientes y notifica la llegada de mercancía.':'Control de distribución y seguimiento de órdenes de compra.'?></p></div><div class="head-side"><span class="user-tag">● <?=gyf_esc((string)($u['nombre']??''))?> · <?=gyf_esc(gyf_role($u))?></span><a class="nav-back" href="<?=gyf_allowed_buy($u)?'erp_compras_inicio.php':'dashboard.php'?>">← Regresar al inicio</a></div></div></header>
<main><?php if($error):?><div class="alert error" role="alert"><?=gyf_esc($error)?></div><?php endif;?><?php if($ok):?><div class="alert" role="status"><?=gyf_esc($ok)?></div><?php endif;?>
<?php
$myOrders=[];$myArrivals=[];
foreach($inbox as $m){if($m['tipo']==='ORDEN' && !isset($myOrders[(int)$m['orden_id']]))$myOrders[(int)$m['orden_id']]=$m;elseif($m['tipo']==='LLEGADA')$myArrivals[]=$m;}
$deliveredCount=0;foreach($myOrders as $m){$oid=(int)$m['orden_id'];if($viewOrder===$oid&&!empty($detalle)){ $pending=0;foreach($detalle as $d)$pending+=max(0,(int)$d['pedido']-(int)$d['aplicadas']);if($pending===0)$deliveredCount++;}}
?>
<?php if(gyf_is_manager($u)):?>
<div class="intro"><div><h2>Mis órdenes de compra</h2><p>Información enviada por Compras a tu sucursal. No necesitas capturar piezas ni facturas.</p></div><span class="pill">Solo órdenes asignadas a tu usuario</span></div>
<div class="stats"><div class="stat"><div class="name">Órdenes recibidas</div><div class="number"><?=count($myOrders)?></div></div><div class="stat"><div class="name">Avisos en mi bandeja</div><div class="number"><?=count($inbox)?></div></div><div class="stat"><div class="name">Órdenes con seguimiento</div><div class="number"><?=$viewOrder>0?1:0?></div></div></div>
<section class="section"><div class="section-title"><div class="symbol">▤</div><div><h2>Órdenes recibidas</h2><p>Consulta el PDF autorizado y avisa a Compras cuando llegue mercancía.</p></div></div>
<?php if(!$myOrders):?><div class="empty"><b>Aún no tienes órdenes asignadas</b>Las órdenes que Compras te envíe aparecerán aquí.</div><?php else:?><div class="orders">
<?php foreach($myOrders as $m):?><article class="order <?=$viewOrder===(int)$m['orden_id']?'active':''?>"><div class="order-top"><div><div class="eyebrow" style="color:#647e94">Orden de compra</div><h3><?=gyf_esc($m['folio'])?></h3></div><span class="pill <?=$m['con_costos']?'green':''?>"><?=$m['con_costos']?'Con costos':'Sin costos'?></span></div><div class="order-body"><div style="font-weight:750;font-size:14px;overflow-wrap:anywhere"><?=gyf_esc($m['proveedor'])?></div><div class="order-detail"><div><span>Recibida</span><strong><?=gyf_esc($m['creado_en'])?></strong></div><div><span>Enviada por</span><strong><?=gyf_esc($m['remitente'])?></strong></div></div></div><div class="order-actions"><a class="btn primary" href="erp_oc_win_pdf.php?id=<?=(int)$m['orden_id']?>&amp;costos=<?=$m['con_costos']?'si':'no'?>" target="_blank" rel="noopener">↗ Ver orden en PDF</a><a class="btn" href="?orden_id=<?=(int)$m['orden_id']?>#seguimiento">◫ Ver pendientes</a></div><form class="delivery" method="post"><input type="hidden" name="csrf" value="<?=gyf_esc(ocw_token())?>"><input type="hidden" name="accion" value="llegada"><input type="hidden" name="orden_id" value="<?=(int)$m['orden_id']?>"><label for="nota-<?=$m['id']?>">¿Ya llegó mercancía de esta orden?</label><textarea id="nota-<?=$m['id']?>" name="nota" maxlength="500" placeholder="Opcional: número de factura, guía u observación de llegada"></textarea><button class="btn primary" type="submit">✓ Notificar llegada a Compras</button><p class="help">Solo informa la llegada. Compras realizará la entrada con la factura.</p></form></article><?php endforeach;?></div><?php endif;?></section>
<?php endif;?>
<?php if(gyf_allowed_buy($u)):?><section class="section"><div class="section-title"><div class="symbol">⇧</div><div><h2>Distribuir órdenes desde Compras</h2><p>Selecciona cómo verá cada gerente la orden; Dirección recibe siempre con costos.</p></div></div><div class="scroll"><table><thead><tr><th>OC</th><th>Proveedor</th><th>Destino</th><th>Enviar</th></tr></thead><tbody><?php foreach($ordenes as $o):?><tr><td><strong><?=gyf_esc($o['folio'])?></strong></td><td><?=gyf_esc($o['proveedor'])?></td><td><?=gyf_esc(ocw_destinos()[$o['destino']]??$o['destino'])?></td><td><form method="post" class="buy-filter"><input type="hidden" name="csrf" value="<?=gyf_esc(ocw_token())?>"><input type="hidden" name="accion" value="enviar"><input type="hidden" name="orden_id" value="<?=(int)$o['id']?>"><select name="costos" aria-label="Mostrar costos al gerente"><option value="no">Gerente sin costos</option><option value="si">Gerente con costos</option></select><button class="btn primary">Enviar en ERP</button></form></td></tr><?php endforeach;?><?php if(!$ordenes):?><tr><td colspan="4">No hay órdenes emitidas disponibles.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<?php if($viewOrder>0):?><section id="seguimiento" class="section"><div class="section-title"><div class="symbol">▥</div><div><h2>Seguimiento de la orden #<?=$viewOrder?></h2><p>Las pendientes se calculan con las entradas de inventario aplicadas desde facturas.</p></div></div>
<?php if(!empty($detalle)):?><div class="scroll"><table><thead><tr><th>Código</th><th>Producto</th><th class="num">Pedido</th><th class="num">Facturado</th><th class="num">Ingresado</th><th class="num">Pendiente</th><th>Avance</th></tr></thead><tbody><?php foreach($detalle as $d):?><?php $pedido=(int)$d['pedido'];$ingresado=(int)$d['aplicadas'];$pendiente=max(0,$pedido-$ingresado);$percentage=$pedido>0?min(100,round(100*$ingresado/$pedido)):100;?><tr><td class="muted"><?=gyf_esc($d['codigo_snapshot'])?></td><td><strong><?=gyf_esc($d['descripcion_snapshot'])?></strong></td><td class="num"><?=$pedido?></td><td class="num"><?=(int)$d['facturadas']?></td><td class="num"><?=$ingresado?></td><td class="num <?=$pendiente===0?'complete':'pending'?>"><?=$pendiente?></td><td><div class="progress" role="progressbar" aria-valuenow="<?=$percentage?>" aria-valuemin="0" aria-valuemax="100" aria-label="Porcentaje ingresado"><div style="width:<?=$percentage?>%"></div></div></td></tr><?php endforeach;?></tbody></table></div><p class="note">Los productos con pendiente cero permanecen visibles aquí como historial; Compras utilizará la vista de pendientes para las siguientes facturas.</p><?php else:?><div class="empty">No hay productos disponibles para mostrar en esta orden.</div><?php endif;?></section><?php endif;?>
<?php if(gyf_allowed_buy($u)):?><section class="section"><div class="section-title"><div class="symbol">♧</div><div><h2>Mi bandeja de avisos</h2><p>Órdenes enviadas, notificaciones de llegada y observaciones recibidas.</p></div></div><div class="scroll"><table class="history"><thead><tr><th>Fecha</th><th>Tipo</th><th>Orden / proveedor</th><th>Remitente</th><th>Nota</th><th>Acción</th></tr></thead><tbody><?php foreach($inbox as $m):?><tr><td><?=gyf_esc($m['creado_en'])?></td><td><span class="pill <?=$m['tipo']==='LLEGADA'?'green':''?>"><?=$m['tipo']==='LLEGADA'?'Llegada notificada':'Orden enviada'?></span></td><td><?=gyf_esc($m['folio'].' · '.$m['proveedor'])?></td><td><?=gyf_esc($m['remitente'])?></td><td><?=gyf_esc($m['nota']??'—')?></td><td><a href="?orden_id=<?=(int)$m['orden_id']?>#seguimiento">Ver seguimiento</a></td></tr><?php endforeach;?><?php if(!$inbox):?><tr><td colspan="6">No tienes avisos aún.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
</main></body></html>
